#!/usr/bin/env python3
"""H7 Set A, job 1: word count -- plain Python. Generated by gen_jobs.py."""
from collections import Counter

with open("/tmp/planes_h7_bench/word_count_input.txt", encoding="utf-8") as f:
    body = f.read()

words = body.split()
total = len(words)
word, count = Counter(words).most_common(1)[0]

print(f"total {total}")
print(f"most {word}")
print(f"count {count}")
